package com.denfense.server.service;
import com.denfense.server.domain.*; import com.denfense.server.dto.battle.BattleSettlementDtos; import com.denfense.server.exception.*; import com.denfense.server.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component @RequiredArgsConstructor public class BattleSettlementWriter { private final BattleSettlementRepository settlements; private final BattlePlayerSettlementRepository players; private final UserRepository users;
 @Transactional(propagation=org.springframework.transaction.annotation.Propagation.REQUIRES_NEW) public BattleSettlement create(BattleSettlementDtos.Request r){BattleSettlement s=new BattleSettlement(r.battleSessionId(),r.requestId(),r.summaryHash(),r.balanceVersion(),r.contentHash(),BattleResult.valueOf(r.result()),r.finalWave(),r.mapId(),r.startedAt(),r.finishedAt());settlements.save(s);for(var p:r.players()){User u=users.findByUsername(p.playerId()).orElseThrow(()->new BusinessException(ErrorCode.BATTLE_PARTICIPANT_MISMATCH));players.save(new BattlePlayerSettlement(s,u,p.playerSlot(),p.eliminated(),p.eliminatedWave(),p.kills(),p.supportKills(),p.bossKills(),p.initialInGameGold(),p.inGameGoldEarned(),p.inGameGoldSpent(),p.finalInGameGold(),p.abandoned()));}settlements.flush();players.flush();return s;}
}
